def maxPathScore(grid, k):
    m, n = len(grid), len(grid[0])
    K = min(k, m + n - 2)   # a path costs at most m + n - 2 (the start cell costs 0)
    NEG = -1                # unreachable (real scores are >= 0)

    # dp[j][c] = best score reaching the current row's column j with total cost exactly c
    dp = [[NEG] * (K + 1) for _ in range(n)]

    for i in range(m):
        for j in range(n):
            v = grid[i][j]
            cost = 1 if v > 0 else 0
            cur = [NEG] * (K + 1)

            if i == 0 and j == 0:
                cur[0] = 0  # grid[0][0] == 0
            else:
                up = dp[j] if i > 0 else None        # cell (i-1, j), still the previous row
                left = dp[j - 1] if j > 0 else None  # cell (i, j-1), already updated for row i
                for c in range(K + 1 - cost):
                    best = NEG
                    if up is not None and up[c] > best:
                        best = up[c]
                    if left is not None and left[c] > best:
                        best = left[c]
                    if best != NEG:
                        cur[c + cost] = best + v
            dp[j] = cur

    res = max(dp[n - 1])
    return res if res != NEG else -1
